  });
});

describe("resolveIntegrationPath", () => {
  it("finds cursor skill in monorepo or bundled package", () => {
    const path = resolveIntegrationPath("cursor", "skills", "duel-agents");
    assert.match(path, /integrations[\\/]cursor[\\/]skills[\\/]duel-agents$/);
  });
});

