export const DEFAULT_PROXY_URL = "https://duelagents.com/v1";
export const DASHBOARD_URL = "https://duelagents.com/dashboard/settings";
export const KEY_DOCS_URL = "https://duelagents.com/dashboard/settings";

/** duel_ + 8-char prefix + _ + 32-char base62 secret */
const API_KEY_PATTERN = /^duel_[0-9a-zA-Z]{8}_[0-9a-zA-Z]{32}$/;

export type InstallTarget =
  | "claude-code"
  | "cursor"
  | "codex"
  | "openclaw"
  | "openai-compat";

export interface ConnectivityResult {
  ok: boolean;
  status: "ok" | "unauthorized" | "unreachable" | "invalid_key";
  message: string;
  httpStatus?: number;
}

/** Returns true only for a well formed \`duel_<prefix>_<secret>\` key. */
export function validateApiKey(plaintext: string | undefined | null): boolean {
  if (!plaintext || typeof plaintext !== "string") return false;
  return API_KEY_PATTERN.test(plaintext);
}

export function requireApiKey(
  input: string | undefined | null,
  label = "DUEL_API_KEY",
): string {
  if (!validateApiKey(input)) {
    throw new Error(
      \`\${label} is required and must be a valid duel_* key. See \${DASHBOARD_URL}\`,
    );
  }
  return input;
}

/** Resolve the proxy URL from env, validated and without a trailing slash. */
export function getProxyUrl(): string {
  const fromEnv = process.env.DUEL_PROXY_URL?.trim();
  const url = fromEnv || DEFAULT_PROXY_URL;
  return url.endsWith("/") ? url.slice(0, -1) : url;
}

/**
 * Build the environment variables a given install target expects. The key is
 * validated first, so callers can rely on the returned values being well formed.
 */
export function getEnvForTarget(
  target: InstallTarget,
  apiKey: string,
  proxyUrl = getProxyUrl(),
): Record<string, string> {
  requireApiKey(apiKey);

  switch (target) {
    case "claude-code":
    case "cursor":
    case "codex":
      return { DUEL_API_KEY: apiKey };
    case "openai-compat":
      return { OPENAI_API_KEY: apiKey, DUEL_PROXY_URL: proxyUrl };
    case "openclaw":
      return {};
    default:
      const _exhaustive: never = target;
      return _exhaustive;
  }
}

/**
 * Build the OpenClaw provider patch. The API key is referenced as
 * \`\${DUEL_API_KEY}\` and never written into the \`env\` block as plaintext.
 */
export function buildOpenClawPatch(
  apiKey: string,
  proxyUrl = getProxyUrl(),
): Record<string, unknown> {
  requireApiKey(apiKey);

  return {
    provider: {
      anthropic: {
        apiKey: "\${DUEL_API_KEY}",
        apiUrl: proxyUrl,
      },
    },
    env: {
      DUEL_API_KEY: apiKey,
    },
  };
}

/** Recursively merge \`patch\` into \`base\`. Arrays and scalars are replaced. */
export function deepMerge(
  base: Record<string, unknown>,
  patch: Record<string, unknown>,
): Record<string, unknown> {
  const result = { ...base };

  for (const key in patch) {
    const patchValue = patch[key];
    const baseValue = result[key];

    if (
      baseValue &&
      typeof baseValue === "object" &&
      !Array.isArray(baseValue) &&
      patchValue &&
      typeof patchValue === "object" &&
      !Array.isArray(patchValue)
    ) {
      result[key] = deepMerge(
        baseValue as Record<string, unknown>,
        patchValue as Record<string, unknown>,
      );
    } else {
      result[key] = patchValue;
    }
  }

  return result;
}

/**
 * Probe the Duel API to confirm a key is accepted. Tries a few read-only
 * endpoints and never throws: connection problems are reported as a result.
 */
export async function checkConnectivity(
  apiKey: string,
  proxyUrl = getProxyUrl(),
): Promise<ConnectivityResult> {
  requireApiKey(apiKey);

  const endpoints = ["/models", "/status"];

  for (const endpoint of endpoints) {
    try {
      const response = await fetch(\`\${proxyUrl}\${endpoint}\`, {
        method: "GET",
        headers: {
          Authorization: \`Bearer \${apiKey}\`,
          "User-Agent": "duel-agents",
        },
      });

      if (response.ok) {
        return {
          ok: true,
          status: "ok",
          message: "Successfully connected to Duel API",
          httpStatus: response.status,
        };
      }

      if (response.status === 401 || response.status === 403) {
        return {
          ok: false,
          status: "unauthorized",
          message: "API key is not valid or not authorized",
          httpStatus: response.status,
        };
      }
    } catch (err) {
      // Continue to next endpoint on network error
      continue;
    }
  }

  return {
    ok: false,
    status: "unreachable",
    message: "Could not reach the Duel API",
  };
}
